assignments.value:
={{
(() => {
  const snippet = $('Gmail Trigger').item.json.snippet || '';

  const pendentesAnterior =
    $('Get row(s) in sheet1').item.json.Informacoes_Pendentes || '';

  // Se já não havia pendências, não criar novas pendências
  if (
    !pendentesAnterior ||
    pendentesAnterior.trim() === '' ||
    pendentesAnterior.trim().toLowerCase() === 'nenhuma'
  ) {
    return 'Nenhuma';
  }

  let pendentes = pendentesAnterior
    .split(',')
    .map(p => p.trim())
    .filter(Boolean);

  const mensagem = snippet.toLowerCase();

  // Remove a pendência de objetivo/descrição somente se
  // o cliente realmente informou essa informação nesta mensagem.
  if (
    /descrição\/objetivo do projeto/i.test(pendentesAnterior) &&
    /objetivo|finalidade|acompanhar|dashboard.*para|projeto.*para/i.test(mensagem)
  ) {
    pendentes = pendentes.filter(
      p => !/descrição\/objetivo do projeto/i.test(p)
    );
  }

  // Remove a pendência de fonte/origem somente se
  // o cliente informou claramente a fonte dos dados.
  if (
    /fonte\/origem dos dados/i.test(pendentesAnterior) &&
    /fonte|origem dos dados|dados.*excel|excel|sql|erp|sistema|banco de dados|csv/i.test(mensagem)
  ) {
    pendentes = pendentes.filter(
      p => !/fonte\/origem dos dados/i.test(p)
    );
  }

  // Remove a pendência de indicadores somente se
  // o cliente informou indicadores/métricas/KPIs.
  if (
    /indicadores\/métricas/i.test(pendentesAnterior) &&
    /indicador|indicadores|métrica|métricas|kpi|resultado esperado/i.test(mensagem)
  ) {
    pendentes = pendentes.filter(
      p => !/indicadores\/métricas/i.test(p)
    );
  }

  return pendentes.length ? pendentes.join(', ') : 'Nenhuma';
})()
}}

