value.Empresa:
={{
(() => {
  const s = $('Gmail Trigger').item.json.snippet || '';

  const m = s.match(
    /Empresa\s*:\s*(.*?)(?=\s+(?:Objetivo|Fonte|Fonte dos dados|Indicadores|Cidade|Telefone|E-mail|Email)\s*:|$)/i
  );

  return m ? m[1].trim() : 'Não informado';
})()
}}

value.cidade:
={{
(() => {
  const s = $('Gmail Trigger').item.json.snippet || '';
  const m = s.match(/Cidade\s*:\s*([^]+?)(?=\s+Telefone\s*:)/i);
  return m ? m[1].trim() : $('Get row(s) in sheet').item.json.cidade;
})()
}}

value.Informacoes_Pendentes:
={{
(() => {
  const s = $('Gmail Trigger').item.json.snippet || '';

  const pendentes = [];

  if (!/objetivo|finalidade|acompanhar|acompanhará|acompanhar as|descrição do projeto/i.test(s)) {
    pendentes.push('Descrição/objetivo do projeto');
  }

  if (!/fonte|origem dos dados|excel|sql|erp|sistema|banco de dados|csv/i.test(s)) {
    pendentes.push('Fonte/origem dos dados');
  }

  if (!/indicador|indicadores|métrica|métricas|kpi|resultado esperado/i.test(s)) {
    pendentes.push('Indicadores/métricas');
  }

  return pendentes.length ? pendentes.join(', ') : 'Nenhuma';
})()
}}
